VALUES (9398, 'tt0196229', NULL, 'Zoolander', 'Zoolander', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/qdrbSneHZjJG2Dj0hhBxzzAo4HB.jpg', 'https://image.tmdb.org/t/p/original/lIyyiBOuyokL82rPEDcZaMKleA3.jpg', 'Clear the runway for Derek Zoolander, VH1''s three-time male model of the year. His face falls when hippie-chic Hansel scooters in to steal this year''s award. The evil fashion guru Mugatu seizes the opportunity to turn Derek into a killing machine. It''s a well-designed conspiracy and only with the help of Hansel and a few well-chosen accessories like Matilda can Derek make the world safe for male models everywhere.', NULL, NULL, 9.2904, 6.229, 0, 1.57061538461538461e+01, '2026-07-15 12:01:52', '2026-10-30 06:04:41')
