VALUES (37707, 'tt1017460', NULL, 'Splice', 'Splice', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/4oqaWnO3dKYAt3vZWAD4oLfOXOC.jpg', 'https://image.tmdb.org/t/p/original/pjocJEjenTiJOi6o1vG8JArgt1h.jpg', 'Elsa and Clive, two young rebellious scientists, defy legal and ethical boundaries and forge ahead with a dangerous experiment: splicing together human and animal DNA to create a new organism. Named "Dren", the creature rapidly develops from a deformed female infant into a beautiful but dangerous winged human-chimera, who forges a bond with both of her creators - only to have that bond turn deadly.', NULL, NULL, 6.5358, 5.888, 0, 24.911875, '2026-08-04 03:20:13', '2026-10-30 06:04:41')
