VALUES (306819, 'tt0810819', NULL, 'The Danish Girl', 'The Danish Girl', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/mXZZIacI5FC8thzSC0lgQBQ2uAX.jpg', 'https://image.tmdb.org/t/p/original/d0tzLbn62WANaq5mnyLpCJsJq1B.jpg', 'When Gerda Wegener asks her husband Einar to fill in as a portrait model, Einar discovers the person she''s meant to be and begins living her life as Lili Elbe. Having realized her true self and with Gerda''s love and support, Lili embarks on a groundbreaking journey as a transgender pioneer.', NULL, NULL, 6.4363, 7.542, 0, 6.15499999999999936e+00, '2026-08-06 03:21:20', '2026-10-30 06:04:41')
