VALUES (82816, 'tt6905686', NULL, 'Lovecraft Country', 'Lovecraft Country', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/fz7bdjxPColvEWCGr5Kiclzc86d.jpg', 'https://image.tmdb.org/t/p/original/qx7qy2GJOc7yGY6WENyBU3OVv7A.jpg', 'The anthology horror series follows 25-year-old Atticus Freeman, who joins up with his friend Letitia and his Uncle George to embark on a road trip across 1950s Jim Crow America to find his missing father. They must survive and overcome both the racist terrors of white America and the malevolent spirits that could be ripped from a Lovecraft paperback.', NULL, NULL, 8.5643, 7.1, 0, 6.52666666666666728e+00, '2026-08-07 03:39:39', '2026-10-30 06:04:41')
