VALUES (243238, 'tt3138282', NULL, 'The Fire Rises: The Creation and Impact of The Dark Knight Trilogy', 'The Fire Rises: The Creation and Impact of The Dark Knight Trilogy', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/y78UlBU4Y2HnEuvSW4V0A5DzP3C.jpg', NULL, 'This feature-length documentary delves into the trilogy, opening with the inspiration and vision for the new Batman films and inching its way toward the Rises finale and the culmination of nearly a decade of creative blood, sweat and tears. Candid, thoughtful and extensive, and comprised of revealing behind-the-scenes footage, countless interviews, audition tapes (with Christian Bale and Cillian Murphy doning the cape and cowl), and a narrative grip and momentum all its own, it leaves no stone unturned.', NULL, NULL, 1.412, 6.875, 0, 3.15, '2026-08-11 22:09:33', '2026-10-30 06:04:41')
